const allEvents = [
  { v: 1, type: "Deposited", amount: 100 },
  { v: 2, type: "Withdrawn", amount: 40 },
  { v: 3, type: "Deposited", amount: 25 },
  { v: 4, type: "Withdrawn", amount: 10 },
  { v: 5, type: "Deposited", amount: 5 }
];
// Drifted snapshot: claims balance 999 at v3 (true folded value is 85). A footgun.
const snapshot = { version: 3, balance: 999 };

function apply(state, e) {
  if (e.type === "Deposited") return { ...state, balance: state.balance + e.amount, version: e.v };
  if (e.type === "Withdrawn") return { ...state, balance: state.balance - e.amount, version: e.v };
  return state;
}
